function IdolLive3D_MainForRuntimeV2:__init()
    self.controller = nil
    self.isInit = false
end


function IdolLive3D_MainForRuntimeV2:__delete()
end



function IdolLive3D_MainForRuntimeV2:Start()
    KTool.SetActive(self.controller.gameObject, true);
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end

    -- PC / Mobile 平台:
    if IdolLive3D_States.expectedPlatformType == IdolLive3D_States.PlatformType.Auto then 
        IdolLive3D_States.isWindowsPlatform = IdolLive3D_Utils.IsReallyPCPlatform() 
    else 
        IdolLive3D_States.isWindowsPlatform = (IdolLive3D_States.expectedPlatformType == IdolLive3D_States.PlatformType.PC)
    end 
end


---@param skinId_ number @ 皮肤id
---@param roleTF_ UnityEngine.Transform @ 角色根节点
---@param runtimeRootTF_ UnityEngine.Transform
---@param superTimelineTFMaps_ table        @ 一组 super timelineStates tfs
---@param allResources_   table
---@param baseJson_ IdolLive3D_BaseParamsJsonDataV2         @ baseParams json 数据 
---@param animatorController_ UnityEngine.RuntimeAnimatorController 
---@param isSmlPackage_ boolean 
---@param isLockFreeCamera_ boolean
---@param isDemo_ boolean   @ 是否是试玩版
function IdolLive3D_MainForRuntimeV2:Init(  skinId_, roleTF_, runtimeRootTF_, superTimelineTFMaps_,
                                            allResources_, baseJson_, animatorController_, isSmlPackage_, isLockFreeCamera_, isDemo_ )
    print("=== IdolLive3D_MainForRuntimeV2 start ===")
    assert( isNotNull(roleTF_) )

    self.skinId = skinId_
    self.baseJson = baseJson_
    self.allResources = allResources_
    ------------------------- 
    self.mainCamera = IdolLive3D_Utils.GetMainCamera()
    assert( isNotNull(self.mainCamera) )

    if isSmlPackage_ == false then
        local uiMainTable = {} 
        Events.Broadcast(IdolLive3D_States.EventGetUIMain, uiMainTable)
        self.uiMain = uiMainTable.uiMain
        assert( isNotNull(self.uiMain) )
    end

    -- ==============================
    self.roleTF = roleTF_
    self.roleLookAtController = KTool.GetComponent(self.roleTF.gameObject, typeof(LookAtController))
    self.roleAnimator = KTool.GetComponent(self.roleTF.gameObject, typeof(Animator))
    assert( isNotNull(self.roleLookAtController) and isNotNull(self.roleAnimator) )

    ---
    local roleLuaParams = KTool.GetComponent(self.roleTF.gameObject, typeof(LuaParameters)) -- maybe nil

    -- 关掉 role 阴影:
    local isCloseShadow = false 
    if isNotNull(roleLuaParams) then 
        isCloseShadow = LuaParametersReader.Read(roleLuaParams, "isCloseShadow", LuaParametersReader.Type.Bool)
    end 
    if isCloseShadow then 
        local planeShadow = KTool.GetComponent(self.roleTF.gameObject, typeof(CS.PlaneShadow))
        if isNotNull(planeShadow) then
            planeShadow.shadowInvLen = 1 -- 写1为关掉
        end
    end 


    -- 
    self.RoleColliderMgr = IdolLive3D_RoleColliderMgr.New( self, self.roleTF )

    -- 在 role 体内准备 CriAtomSource go:
    IdolLive3D_Sounds:AddCRIAtomSource_SFX( roleTF_ )

    ---
    self.idolLive3D_FreeNodesMgr = IdolLive3D_FreeNodesMgr.New()

    
    -- (1) 先置空, 避免下面开启 IK 时角色不在 T-pos:
    self.roleAnimator.runtimeAnimatorController = nil
    
    -- (2) 主动开启 IK:  
    local lookAtIK = KTool.GetComponent(self.roleTF.gameObject, typeof(LookAtIK))
    assert(lookAtIK)
    lookAtIK.enabled = true

    --
    self.roleAnimatorMgr = IdolLive3D_RoleAnimatorMgrV2B.New( self, self.roleAnimator, animatorController_ ) 
    self.roleAnimatorMgr:SwitchToNewStage( self.baseJson.data.enterMgr.initStage )

    --
    if not (self.baseJson.data.oths.debugParams.DisableRoleIK == true) then
        self.roleIKMgr = IdolLive3D_RoleIKMgr.New( self, roleTF_ )
    else 
        local fullBodyBipedIK = KTool.GetComponent(self.roleTF.gameObject, typeof(FullBodyBipedIK))
        if isNotNull(fullBodyBipedIK) then 
            fullBodyBipedIK.enabled = false
        end
    end

    self.fakeIKMgr = IdolLive3D_FakeIKMgr.New( self, roleTF_ )



    -- 绑定 customLightDirRelativeCamera.RelativeCamera:
    -- 有些 角色 prefab 可能不带此组件
    self.customLightDirRelativeCamera = KTool.GetOrAddComponent(self.roleTF.gameObject, typeof(CustomLightDirRelativeCamera))
    if isNull(self.customLightDirRelativeCamera) then 
        printError("koko - 异常, role 没绑定 self.CustomLightDirRelativeCamera 脚本")
        return
    end
    self.customLightDirRelativeCamera.RelativeCamera = self.mainCamera
    self.customLightDirRelativeCamera.DelayUpdate = true

    ------------------
    assert(self.idolCamera) 
    ---@type IdolLive3D_CameraV2
    self.idolLive3D_CameraEnv = IdolLive3D_Utils.GetLuaScr(self.idolCamera.gameObject, "Game.IdolLive3D.V2.IdolLive3D_CameraV2" )
    assert( self.idolLive3D_CameraEnv )
    self.idolLive3D_CameraEnv:Init(self)

    ---
    assert(self.idolInteractive) 
    ---@type IdolLive3D_InteractiveManager
    self.idolLive3D_InteractiveManagerEnv = IdolLive3D_Utils.GetLuaScr(self.idolInteractive.gameObject, "Game.IdolLive3D.V2.IdolLive3D_InteractiveManagerV2" )
    assert( self.idolLive3D_InteractiveManagerEnv )
    self.idolLive3D_InteractiveManagerEnv:Init(self, runtimeRootTF_, self.idolLive3D_CameraEnv, lookAtIK, self.roleAnimator, superTimelineTFMaps_, allResources_ )

    ---
    assert(self.idolTextDebug) 
    ---@type IdolLive3D_TextDebug
    self.idolLive3D_TextDebugEnv = IdolLive3D_Utils.GetLuaScr(self.idolTextDebug.gameObject, "Game.IdolLive3D.IdolLive3D_TextDebug" )
    assert( self.idolLive3D_TextDebugEnv )

    ---@type IdolLive3D_InputV2
    self.idolLive3D_Input = IdolLive3D_InputV2.New(self)


    -- 反绑参数:
    self.idolLive3D_InteractiveManagerEnv:BindSimpleTap( self.idolLive3D_Input )
    self.idolLive3D_CameraEnv:BindInput( self.idolLive3D_Input )

    if isNotNull(self.roleIKMgr) then 
        self.roleIKMgr:BindInput( self.idolLive3D_Input )
    end


    if isSmlPackage_==true and isLockFreeCamera_==true then 
        -- 二段包的一种入场方式: 进去就 cut 到一个近景, 且锁 free camera
        -- !!! 这里的时序出问题了, 如果不等到两帧再执行, 会导致这个镜头锁定被丢失; 先用以下暴力方法克服, 晚点来实现正式修改
        IdolLive3D_Utils.StopCoroutine(self.co_3)
        self.co_3 = cs_coroutine.start(function()
            coroutine.yield(Yielders.EndOfFrame)
            coroutine.yield(Yielders.EndOfFrame)
            self.idolLive3D_CameraEnv:InitToFreezeState( IdolLive3D_States.GameInstaller.tgtFreeCameraParams, true )
        end)
    end 

    --- 所有需要跟着 role 一起移动的 go tfs:
    self.allRoleTFs = { roleTF_ }
    for _,se in pairs(superTimelineTFMaps_) do -- each superTL:
        for __,tfs in pairs(se) do -- each clip:
            for ___,tf in pairs(tfs) do -- tfs.main, tfs.fakeIK, tfs.loopFakeIK, 
                table.insert( self.allRoleTFs, tf )
            end 
        end
    end

    --------- 皮肤定制脚本 --------
    local skinLuaEnv = self.baseJson.data.oths.skinLuaEnv
    if isNotNull(skinLuaEnv) and isNotNull(skinLuaEnv.OnMainInitEnd) then 
        skinLuaEnv:OnMainInitEnd( self )
    end

    --
    self.isInit = true
end



function IdolLive3D_MainForRuntimeV2:OnDestroy()
    if isNotNull(self.idolLive3D_Input) then 
        self.idolLive3D_Input:Delete() -- !! MUST
    end 
    if isNotNull(self.idolLive3D_FreeNodesMgr) then 
        self.idolLive3D_FreeNodesMgr:Delete() -- !! MUST
    end 
    if isNotNull(self.roleIKMgr) then 
        self.roleIKMgr:Delete() -- !! MUST
    end
    if isNotNull(self.RoleColliderMgr) then 
        self.RoleColliderMgr:Delete() -- !! MUST
    end 

    IdolLive3D_Utils.StopCoroutine(self.co_1)
    IdolLive3D_Utils.StopCoroutine(self.co_2)
    IdolLive3D_Utils.StopCoroutine(self.co_3)

    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


-- ===============================================================


function IdolLive3D_MainForRuntimeV2:IsInit()
    return (self.isInit == true)
end



function IdolLive3D_MainForRuntimeV2:Update()
    if self.isInit ~= true then 
        return
    end
    self.idolLive3D_Input:SelfUpdate()
    self.idolLive3D_InteractiveManagerEnv:SelfUpdate()
    self.idolLive3D_CameraEnv:SelfUpdate()

    if isNotNull(self.roleIKMgr) then
        self.roleIKMgr:SelfUpdate()
    end

    for _,fullScreenFXEnv in pairs(self.allResources.fullScreenFXEnvs) do 
        fullScreenFXEnv:SelfUpdate()
    end    
end


function IdolLive3D_MainForRuntimeV2:OnSwitchStage( newStageJson_ )
    local rolePos = newStageJson_.roleParams.rolePos
    local roleRotation = newStageJson_.roleParams.roleRotation
    for _,tf in pairs(self.allRoleTFs) do 
        tf.position = rolePos
        tf.rotation = roleRotation
    end
    for _,tf in pairs(newStageJson_.simpleFxTFMaps) do 
        tf.position = rolePos
        tf.rotation = roleRotation
    end
    ---
    
    ---
    if newStageJson_.roleParams.customLightDir.magnitude > 0.01 then 
        self.customLightDirRelativeCamera.CustomLightDirection = newStageJson_.roleParams.customLightDir
    end   

    if isNotNull(self.roleIKMgr) then
        self.roleIKMgr:IntoNewState( newStageJson_.idleState.IKParams )
    end

    self.RoleColliderMgr:IntoNewState( newStageJson_.allTouchKeys )
    
    if isNotNull(self.uiMain) then 
        self.uiMain:IntoNewState( newStageJson_.uiMgr )
    end 

    self.idolLive3D_InteractiveManagerEnv:IntoNewState()

    
    --------- 皮肤定制脚本 --------
    local skinLuaEnv = self.baseJson.data.oths.skinLuaEnv
    if isNotNull(skinLuaEnv) and isNotNull(skinLuaEnv.OnSwitchStageEnd) then 
        skinLuaEnv:OnSwitchStageEnd( self, newStageJson_ )
    end

end






return IdolLive3D_MainForRuntimeV2
